            if grid[r][c]==2 and (r,c) not in seen:
                st=[(r,c)]; seen.add((r,c)); cc=[]
                while st:
                    a,b=st.pop(); cc.append((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
