def comps8(g):
    seen=set(); out=[]
    for r in range(len(g)):
        for c in range(len(g[0])):
            if g[r][c] and (r,c) not in seen:
                st=[(r,c)]; comp=[]
                while st:
                    p=st.pop()
                    if p in seen or not g[p[0]][p[1]]: continue
                    seen.add(p); comp.append(p)
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            q=(p[0]+dr,p[1]+dc)
                            if 0<=q[0]<len(g) and 0<=q[1]<len(g[0]): st.append(q)
                out.append(comp)
    return out
